-- ##################### 001_schema.sql #####################
-- =====================================================================
-- KiteCab v2 — core schema
-- Run in Supabase SQL editor (or `supabase db push`).
-- Creates NEW objects only. The live tables `kitecab` and `payments` are
-- never altered (no columns, indexes, grants or policies are added to them).
-- =====================================================================
begin;

-- ---------- enums ----------------------------------------------------
create type public.booking_type   as enum ('oneway', 'round-trip', 'local-rental');
create type public.car_type       as enum ('Hatchback', 'Sedan', 'SUV');
create type public.booking_status as enum ('new', 'confirmed', 'assigned', 'completed', 'cancelled');
create type public.user_role      as enum ('admin', 'driver', 'customer');
create type public.driver_status  as enum ('pending', 'approved', 'suspended');

-- ---------- helpers --------------------------------------------------
create function public.slugify(txt text)
returns text language sql immutable as $$
  select trim(both '-' from regexp_replace(lower(coalesce(txt, '')), '[^a-z0-9]+', '-', 'g'))
$$;

create function public.touch_updated_at()
returns trigger language plpgsql as $$
begin
  new.updated_at := now();
  return new;
end $$;

-- ---------- settings (everything that may change later) --------------
-- One row per setting. `is_public` rows are readable by the website.
create table public.settings (
  key         text primary key,
  value       jsonb not null,
  is_public   boolean not null default false,
  description text,
  updated_at  timestamptz not null default now()
);

insert into public.settings (key, value, is_public, description) values
  ('advance_percent',        '20',                                  true,  'Advance % charged via Razorpay link'),
  ('whatsapp_sender',        '"919009611602"',                      false, 'MSG91 integrated WhatsApp number'),
  ('whatsapp_namespace',     '"5f6d7b38_402c_4432_b048_6a2ad7492956"', false, 'MSG91 template namespace'),
  ('admin_whatsapp_numbers', '["918187962796","916263676216","918963952633"]', false, 'Numbers that receive admin alerts'),
  ('support_phone',          '"+919009611602"',                     true,  'Call / WhatsApp number shown on site'),
  ('support_email',          '"kitecabtaxiservice@gmail.com"',      true,  'Email shown on site and invoice'),
  ('business',               '{"name":"KiteCab","address":"","gstin":""}', true, 'Invoice header details'),
  ('booking_open',           'true',                                true,  'Master switch: accept online bookings');

-- ---------- locations & fares ----------------------------------------
create table public.locations (
  id          bigint generated always as identity primary key,
  name        text not null unique,
  slug        text not null unique,
  state       text not null default 'CG',       -- CG, MH, BR, OD ...
  is_active   boolean not null default true,     -- admin can switch off temporarily
  is_featured boolean not null default false,    -- Raipur, Bilaspur ... (SEO city pages first)
  sort_order  int not null default 100,
  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now()
);

-- One-way fares (pickup -> drop). Reverse direction is its own row.
create table public.routes (
  id               bigint generated always as identity primary key,
  from_location_id bigint not null references public.locations(id) on delete restrict,
  to_location_id   bigint not null references public.locations(id) on delete restrict,
  distance_km      int not null check (distance_km > 0),
  hatchback_price  int not null check (hatchback_price > 0),
  sedan_price      int not null check (sedan_price > 0),
  suv_price        int not null check (suv_price > 0),
  is_active        boolean not null default true,
  legacy_id        bigint,
  created_at       timestamptz not null default now(),
  updated_at       timestamptz not null default now(),
  unique (from_location_id, to_location_id),
  check (from_location_id <> to_location_id)
);
create index routes_to_idx on public.routes (to_location_id);

create table public.rental_packages (
  id              bigint generated always as identity primary key,
  hours           int not null check (hours > 0),
  km              int not null check (km > 0),
  hatchback_price int not null check (hatchback_price > 0),
  sedan_price     int not null check (sedan_price > 0),
  suv_price       int not null check (suv_price > 0),
  is_active       boolean not null default true,
  legacy_id       bigint,
  created_at      timestamptz not null default now(),
  updated_at      timestamptz not null default now(),
  unique (hours, km)
);

-- Round trip fare = per_km * approx_km + base   (per car type, per waiting slot)
create table public.round_trip_rates (
  id                 bigint generated always as identity primary key,
  waiting_slot       text not null unique,        -- '1-3 hours', '1 day' ...
  sort_order         int not null default 100,
  hatchback_per_km   int not null, sedan_per_km int not null, suv_per_km int not null,
  hatchback_base     int not null, sedan_base   int not null, suv_base   int not null,
  is_active          boolean not null default true,
  updated_at         timestamptz not null default now()
);

-- Current formula from the live site (cab-round-trip-dialog.component.ts)
insert into public.round_trip_rates
  (waiting_slot, sort_order, hatchback_per_km, sedan_per_km, suv_per_km, hatchback_base, sedan_base, suv_base) values
  ('1-3 hours', 1, 10, 11, 16, 1200, 1200, 1400),
  ('3-6 hours', 2, 10, 11, 16, 1200, 1200, 1400),
  ('6-9 hours', 3, 10, 11, 16, 1300, 1300, 1500),
  ('1 day',     4, 10, 11, 16, 1400, 1500, 1600),
  ('2 day',     5, 10, 11, 16, 2800, 3000, 3200),
  ('3 day',     6, 10, 11, 16, 4200, 4500, 4800);

-- ---------- people (future-proof: customer & driver logins) ----------
-- One row per Supabase Auth login.
create table public.profiles (
  id         uuid primary key references auth.users(id) on delete cascade,
  role       public.user_role not null default 'customer',
  full_name  text,
  mobile     text,
  created_at timestamptz not null default now()
);

-- Everyone who books. auth_user_id is filled only when they create a login.
create table public.customers (
  id           bigint generated always as identity primary key,
  auth_user_id uuid unique references auth.users(id) on delete set null,
  full_name    text not null,
  mobile       text not null unique,
  email        text,
  created_at   timestamptz not null default now(),
  updated_at   timestamptz not null default now()
);

create table public.drivers (
  id               bigint generated always as identity primary key,
  auth_user_id     uuid unique references auth.users(id) on delete set null,
  full_name        text not null,
  mobile           text not null unique,
  alt_mobile       text,
  license_no       text,
  license_expiry   date,
  base_location_id bigint references public.locations(id),
  status           public.driver_status not null default 'pending',
  rating           numeric(2,1),
  notes            text,
  created_at       timestamptz not null default now(),
  updated_at       timestamptz not null default now()
);

create table public.vehicles (
  id               bigint generated always as identity primary key,
  driver_id        bigint references public.drivers(id) on delete set null,
  registration_no  text not null unique,
  car_type         public.car_type not null,
  model            text,
  seats            int,
  insurance_expiry date,
  permit_expiry    date,
  puc_expiry       date,
  is_active        boolean not null default true,
  created_at       timestamptz not null default now(),
  updated_at       timestamptz not null default now()
);

-- Files live in a PRIVATE storage bucket; only the path is stored here.
create table public.driver_documents (
  id          bigint generated always as identity primary key,
  driver_id   bigint not null references public.drivers(id) on delete cascade,
  doc_type    text not null,           -- license, rc, insurance, id_proof, photo
  file_path   text not null,
  verified    boolean not null default false,
  uploaded_at timestamptz not null default now()
);

-- ---------- enquiries & bookings -------------------------------------
create table public.enquiries (
  id              bigint generated always as identity primary key,
  service_type    public.booking_type,
  pickup          text not null,
  drop_or_package text,
  mobile          text,                -- null when customer typed an invalid number
  created_at      timestamptz not null default now(),
  legacy_id       bigint
);
create index enquiries_created_idx on public.enquiries (created_at desc);

-- Booking IDs continue the legacy sequence (invoice no = id + 5125).
create table public.bookings (
  id                 bigint generated by default as identity (start with 999970) primary key,
  booking_type       public.booking_type not null,
  car_type           public.car_type not null,
  status             public.booking_status not null default 'new',

  -- trip (names are copied so history survives later renames/deletes)
  pickup_location    text not null,
  drop_location      text,
  route_id           bigint references public.routes(id) on delete set null,
  rental_package_id  bigint references public.rental_packages(id) on delete set null,
  rental_package     text,             -- e.g. '8 hours 80 km'
  waiting_time       text,             -- round trip slot
  approx_distance_km int,              -- round trip
  distance_km        int,

  -- money (always calculated on the server)
  fare               int not null check (fare >= 0),
  advance_percent    numeric(5,2),
  advance_amount     int,

  -- customer snapshot
  customer_id        bigint references public.customers(id) on delete set null,
  customer_name      text not null,
  mobile             text not null,
  email              text,
  passengers         int not null default 1 check (passengers > 0),
  pickup_address     text not null,
  pickup_date        date not null,
  pickup_time        text not null,

  -- operations
  driver_id          bigint references public.drivers(id) on delete set null,
  vehicle_id         bigint references public.vehicles(id) on delete set null,
  assigned_at        timestamptz,
  admin_notes        text,

  legacy_id          bigint,
  created_at         timestamptz not null default now(),
  updated_at         timestamptz not null default now()
);
create index bookings_pickup_date_idx on public.bookings (pickup_date desc);
create index bookings_created_idx     on public.bookings (created_at desc);
create index bookings_mobile_idx      on public.bookings (mobile);
create index bookings_customer_idx    on public.bookings (customer_id);
create index bookings_driver_idx      on public.bookings (driver_id);

create table public.booking_status_history (
  id          bigint generated always as identity primary key,
  booking_id  bigint not null references public.bookings(id) on delete cascade,
  from_status public.booking_status,
  to_status   public.booking_status not null,
  changed_by  uuid references auth.users(id),
  note        text,
  created_at  timestamptz not null default now()
);

create function public.log_booking_status()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if tg_op = 'INSERT' or new.status is distinct from old.status then
    insert into public.booking_status_history (booking_id, from_status, to_status, changed_by)
    values (new.id, case when tg_op = 'UPDATE' then old.status end, new.status, auth.uid());
  end if;
  return new;
end $$;

create trigger bookings_status_log
  after insert or update of status on public.bookings
  for each row execute function public.log_booking_status();

-- ---------- payments (NEW table; the live `payments` table is only read) --
create table public.booking_payments (
  id                       bigint generated always as identity primary key,
  booking_id               bigint not null,
  customer_name            text not null,
  mobile                   text not null,
  booking_amount           int not null,
  advance_amount           int not null,
  payment_type             text not null default 'ADVANCE',
  status                   text not null default 'PENDING'
                             check (status in ('PENDING', 'PAID', 'EXPIRED', 'CANCELLED', 'FAILED')),
  payment_link             text,
  razorpay_payment_link_id text not null unique,
  razorpay_payment_id      text unique,
  reference_id             text,
  attempt                  int not null default 1,   -- admin "new link" uses attempt + 1
  amount_paid              int,
  paid_at                  timestamptz,
  webhook_response         jsonb,
  legacy_id                bigint,                   -- id in the old `payments` table
  created_at               timestamptz not null default now(),
  updated_at               timestamptz not null default now()
);
create index booking_payments_booking_idx on public.booking_payments (booking_id);
create index booking_payments_created_idx on public.booking_payments (created_at desc);

-- ---------- updated_at triggers --------------------------------------
do $$
declare t text;
begin
  foreach t in array array['locations','routes','rental_packages','round_trip_rates',
                           'customers','drivers','vehicles','bookings','settings','booking_payments']
  loop
    execute format('create trigger %I_touch before update on public.%I
                    for each row execute function public.touch_updated_at()', t, t);
  end loop;
end $$;

-- ---------- public read views (what the website may see) -------------
create view public.route_fares with (security_invoker = true) as
select r.id,
       f.name as pickup, f.slug as pickup_slug,
       t.name as drop,   t.slug as drop_slug,
       f.slug || '-to-' || t.slug as slug,
       r.distance_km, r.hatchback_price, r.sedan_price, r.suv_price
from public.routes r
join public.locations f on f.id = r.from_location_id and f.is_active
join public.locations t on t.id = r.to_location_id   and t.is_active
where r.is_active;

commit;

-- ##################### 002_rls.sql #####################
-- =====================================================================
begin;
-- KiteCab v2 — Row Level Security
-- Rule of thumb:
--   * website visitors (anon)  -> read active fares + public settings only
--   * all writes from the site -> go through the backend (service key)
--   * admin                    -> full access via Supabase Auth login
--   * driver / customer        -> only their own rows (future logins)
-- The live `kitecab` and `payments` tables are NOT touched here.
-- =====================================================================

create function public.current_role_is(r public.user_role)
returns boolean language sql stable security definer set search_path = public as $$
  select exists (select 1 from public.profiles p where p.id = auth.uid() and p.role = r)
$$;

create function public.is_admin()
returns boolean language sql stable as $$ select public.current_role_is('admin') $$;

-- enable RLS everywhere (no policy = no access)
alter table public.settings               enable row level security;
alter table public.locations              enable row level security;
alter table public.routes                 enable row level security;
alter table public.rental_packages        enable row level security;
alter table public.round_trip_rates       enable row level security;
alter table public.profiles               enable row level security;
alter table public.customers              enable row level security;
alter table public.drivers                enable row level security;
alter table public.vehicles               enable row level security;
alter table public.driver_documents       enable row level security;
alter table public.enquiries              enable row level security;
alter table public.bookings               enable row level security;
alter table public.booking_status_history enable row level security;
alter table public.booking_payments       enable row level security;

-- ---------- public catalogue -----------------------------------------
create policy "public read active locations" on public.locations
  for select using (is_active or public.is_admin());
create policy "public read active routes" on public.routes
  for select using (is_active or public.is_admin());
create policy "public read active rentals" on public.rental_packages
  for select using (is_active or public.is_admin());
create policy "public read active round trip" on public.round_trip_rates
  for select using (is_active or public.is_admin());
create policy "public read public settings" on public.settings
  for select using (is_public or public.is_admin());

-- ---------- admin: full access to everything -------------------------
do $$
declare t text;
begin
  foreach t in array array['settings','locations','routes','rental_packages','round_trip_rates',
                           'profiles','customers','drivers','vehicles','driver_documents',
                           'enquiries','bookings','booking_status_history','booking_payments']
  loop
    execute format('create policy "admin all %1$s" on public.%1$I
                    for all using (public.is_admin()) with check (public.is_admin())', t);
  end loop;
end $$;

-- ---------- own rows (future customer / driver logins) ----------------
create policy "read own profile" on public.profiles
  for select using (id = auth.uid());

create policy "customer reads self" on public.customers
  for select using (auth_user_id = auth.uid());
create policy "customer reads own bookings" on public.bookings
  for select using (customer_id in (select id from public.customers where auth_user_id = auth.uid()));

create policy "driver reads self" on public.drivers
  for select using (auth_user_id = auth.uid());
create policy "driver reads assigned bookings" on public.bookings
  for select using (driver_id in (select id from public.drivers where auth_user_id = auth.uid()));
create policy "driver reads own vehicles" on public.vehicles
  for select using (driver_id in (select id from public.drivers where auth_user_id = auth.uid()));
create policy "driver reads own documents" on public.driver_documents
  for select using (driver_id in (select id from public.drivers where auth_user_id = auth.uid()));

-- ---------- table grants (RLS still applies on top) -------------------
-- Only NEW tables are touched; legacy `kitecab` / `payments` grants stay as-is.
revoke all on public.settings, public.locations, public.routes, public.rental_packages,
              public.round_trip_rates, public.route_fares, public.profiles, public.customers,
              public.drivers, public.vehicles, public.driver_documents, public.enquiries,
              public.bookings, public.booking_status_history,
              public.booking_payments
  from anon, authenticated;
grant select on public.settings, public.locations, public.routes, public.rental_packages,
                public.round_trip_rates, public.route_fares to anon, authenticated;
grant insert, update, delete on public.settings, public.locations, public.routes,
                public.rental_packages, public.round_trip_rates to authenticated;
grant select, insert, update, delete on public.profiles, public.customers, public.drivers,
                public.vehicles, public.driver_documents, public.enquiries, public.bookings,
                public.booking_status_history, public.booking_payments to authenticated;

-- ---------- admin bootstrap -------------------------------------------
-- 1. Supabase dashboard -> Authentication -> Users -> Add user
--    (kitecabtaxiservice@gmail.com, strong password, auto-confirm)
-- 2. Then run:
--    insert into public.profiles (id, role, full_name)
--    select id, 'admin', 'KiteCab Admin' from auth.users
--    where email = 'kitecabtaxiservice@gmail.com'
--    on conflict (id) do update set role = 'admin';

commit;

-- ##################### 003_migrate_legacy_data.sql #####################
-- =====================================================================
-- KiteCab v2 — copy legacy JSON data (table `kitecab`) into new tables
--
-- * Re-runnable until launch: it EMPTIES the new tables first, then
--   rebuilds them from the legacy rows. Run it one final time at cutover.
-- * Only READS the live `kitecab` and `payments` tables — never changes them.
-- * Uses your data and prices exactly; only cleans obvious junk:
--     - trims spaces, 'Arrah(BR)' -> 'Arrah (BR)'
--     - drops empty rows and testingPickup/testingDrop
--     - duplicate route (same pickup+drop): keeps the most recently added one
--     - car/booking type spelling ('Suv', 'Sedam', 'Round Trip ') unified
--     - enquiry mobile '0000000000' / invalid -> NULL
--     - duplicate booking id: 2nd copy gets a new id (legacy_id keeps the old)
--     - passengers outside 1..20 (people typed phone numbers there) -> 1
-- =====================================================================
begin;

-- ---------- helpers (temporary, dropped at end of session) -----------
create or replace function pg_temp.to_int(t text) returns int language sql immutable as $$
  select case when trim(coalesce(t, '')) ~ '^\d{1,9}(\.\d+)?$' then round(trim(t)::numeric)::int end
$$;

create or replace function pg_temp.place(t text) returns text language sql immutable as $$
  select nullif(regexp_replace(regexp_replace(trim(coalesce(t, '')), '\s*\(', ' ('), '\s+', ' ', 'g'), '')
$$;

create or replace function pg_temp.car(t text) returns public.car_type language sql immutable as $$
  select case
    when lower(trim(t)) like 'suv%'   then 'SUV'
    when lower(trim(t)) like 'sed%'   then 'Sedan'
    else 'Hatchback' end::public.car_type
$$;

create or replace function pg_temp.btype(t text) returns public.booking_type language sql immutable as $$
  select case
    when lower(t) like '%rental%' then 'local-rental'
    when lower(t) like 'round%'   then 'round-trip'
    else 'oneway' end::public.booking_type
$$;

-- 'Thu Sep 24 2026' (new) or '2024-11-28T18:30:00.000Z' (IST midnight saved as UTC)
create or replace function pg_temp.pickup_date(t text) returns date language sql immutable as $$
  select case
    when t ~ '^\d{4}-\d{2}-\d{2}T' then (t::timestamptz at time zone 'Asia/Kolkata')::date
    when t ~ '^[A-Za-z]{3} [A-Za-z]{3} \d{2} \d{4}$' then to_date(substr(t, 5), 'Mon DD YYYY')
  end
$$;

create or replace function pg_temp.mobile(t text) returns text language sql immutable as $$
  select case when trim(coalesce(t, '')) ~ '^[6-9]\d{9}$' then trim(t) end
$$;

-- enquiry date/time came in many shapes: '1/5/2026' '01/05/2026' '2026-05-01'
-- and '08:53:38' '8:53:38 PM' '04:51 pm' ... -> IST timestamp (NULL if unreadable)
create or replace function pg_temp.enquiry_ts(d text, t text) returns timestamptz language plpgsql immutable as $$
declare dm text[]; tm text[]; a int; b int; y int; h int; mi int; se int; dt date;
begin
  if d ~ '^\d{4}-\d{2}-\d{2}' then
    dt := substr(d, 1, 10)::date;
  else
    dm := regexp_match(trim(d), '^(\d{1,2})/(\d{1,2})/(\d{4})$');
    if dm is null then return null; end if;
    a := dm[1]::int; b := dm[2]::int; y := dm[3]::int;
    if b > 12 then dt := make_date(y, a, b);       -- clearly M/D/Y
    else
      dt := make_date(y, b, a);                    -- D/M/Y (India)
      -- a future date means the browser saved it as M/D/Y
      if dt > current_date and a <= 12 then dt := make_date(y, a, b); end if;
    end if;
  end if;
  tm := regexp_match(trim(coalesce(t, '')), '^(\d{1,2}):(\d{2})(?::(\d{2}))?\s*([AaPp][Mm])?$');
  if tm is null then return dt::timestamp at time zone 'Asia/Kolkata'; end if;
  h := tm[1]::int; mi := tm[2]::int; se := coalesce(tm[3], '0')::int;
  if lower(tm[4]) = 'pm' and h < 12 then h := h + 12; end if;
  if lower(tm[4]) = 'am' and h = 12 then h := 0; end if;
  return (dt + make_time(h, mi, se)) at time zone 'Asia/Kolkata';
exception when others then
  return null;
end $$;

create or replace function pg_temp.legacy(k text) returns setof jsonb language sql stable as $$
  select e from public.kitecab k2, jsonb_array_elements(k2.value) with ordinality as x(e, n)
  where k2.key = k order by n
$$;

-- ---------- reset new tables -----------------------------------------
truncate public.booking_payments, public.booking_status_history, public.bookings, public.customers,
         public.enquiries, public.routes, public.rental_packages, public.locations
  restart identity cascade;

alter table public.bookings disable trigger bookings_status_log;

-- ---------- locations ------------------------------------------------
with raw as (
  select pg_temp.place(e->>'pickup') as name from pg_temp.legacy('locationPrices') e
  union
  select pg_temp.place(e->>'dropoff') from pg_temp.legacy('locationPrices') e
)
insert into public.locations (name, slug, state, is_featured, sort_order)
select name,
       public.slugify(name),
       coalesce(substring(name from '\(([A-Z]{2})\)$'), 'CG'),
       name in ('Raipur', 'Bilaspur', 'Durg', 'Bhilai', 'Raigarh', 'Nagpur (MH)'),
       case name when 'Raipur' then 1 when 'Bilaspur' then 2 when 'Durg' then 3
                 when 'Bhilai' then 4 when 'Raigarh' then 5 when 'Nagpur (MH)' then 6 else 100 end
from raw
where name is not null and name not ilike 'testing%'
order by name;

-- ---------- routes ---------------------------------------------------
with src as (
  select e, row_number() over () as n from pg_temp.legacy('locationPrices') e
), clean as (
  select distinct on (f.id, t.id)
         f.id as from_id, t.id as to_id,
         pg_temp.to_int(e->>'distance')   as distance_km,
         pg_temp.to_int(e->>'price')      as hatchback_price,
         pg_temp.to_int(e->>'sedanPrice') as sedan_price,
         pg_temp.to_int(e->>'suvPrice')   as suv_price,
         coalesce((e->>'active')::boolean, true) as is_active,
         (e->>'id')::bigint as legacy_id
  from src
  join public.locations f on f.name = pg_temp.place(e->>'pickup')
  join public.locations t on t.name = pg_temp.place(e->>'dropoff')
  where f.id <> t.id
  order by f.id, t.id, n desc                      -- latest entry wins
)
insert into public.routes (from_location_id, to_location_id, distance_km,
                           hatchback_price, sedan_price, suv_price, is_active, legacy_id)
select from_id, to_id, distance_km, hatchback_price, sedan_price, suv_price, is_active, legacy_id
from clean
where distance_km > 0 and hatchback_price > 0 and sedan_price > 0 and suv_price > 0;

-- ---------- rental packages ------------------------------------------
insert into public.rental_packages (hours, km, hatchback_price, sedan_price, suv_price, legacy_id)
select pg_temp.to_int(substring(e->>'time' from '\d+')),
       pg_temp.to_int(e->>'distance'),
       pg_temp.to_int(e->>'hatchbackPrice'),
       pg_temp.to_int(e->>'sedanPrice'),
       pg_temp.to_int(e->>'suvPrice'),
       (e->>'id')::bigint
from pg_temp.legacy('rentalPackages') e
order by 1;

-- ---------- bookings -------------------------------------------------
create temp table legacy_bookings on commit drop as
select (e->>'id')::bigint as legacy_id,
       row_number() over (partition by e->>'id' order by n) as copy_no,
       n,
       e->'customerDetail' as c,
       e->'bookingDetail'  as b
from (select e, row_number() over () as n from pg_temp.legacy('customersRecord') e) s;

create temp table booking_rows on commit drop as
select lb.legacy_id, lb.copy_no, lb.n,
       pg_temp.btype(b->>'bookingType')                         as booking_type,
       pg_temp.car(b->>'carType')                               as car_type,
       coalesce(pg_temp.place(b->>'pickupLocation'), '-')       as pickup_location,
       pg_temp.place(b->>'dropLocation')                        as drop_location,
       nullif(trim(b->>'package'), '')                          as rental_package,
       nullif(trim(b->>'waitingTime'), '')                      as waiting_time,
       pg_temp.to_int(b->>'approxDistance')                     as approx_distance_km,
       pg_temp.to_int(b->>'distance')                           as distance_km,
       coalesce(pg_temp.to_int(b->>'price'), 0)                 as fare,
       coalesce(nullif(trim(c->>'fullName'), ''), '-')          as customer_name,
       trim(coalesce(c->>'mobileNumber', ''))                   as mobile,
       nullif(trim(c->>'email'), '')                            as email,
       case when pg_temp.to_int(c->>'numberOfPassengers') between 1 and 20
            then pg_temp.to_int(c->>'numberOfPassengers') else 1 end  as passengers,
       coalesce(nullif(trim(c->>'pickupAddress'), ''), '-')     as pickup_address,
       pg_temp.pickup_date(c->>'pickupDate')                    as pickup_date,
       coalesce(nullif(trim(c->>'pickupTime'), ''), '-')        as pickup_time
from legacy_bookings lb;

-- first copy keeps its original id (invoice numbers stay the same)
insert into public.bookings (id, booking_type, car_type, pickup_location, drop_location,
       rental_package, waiting_time, approx_distance_km, distance_km, fare,
       customer_name, mobile, email, passengers, pickup_address, pickup_date, pickup_time,
       advance_amount, legacy_id, created_at)
overriding system value
select r.legacy_id, r.booking_type, r.car_type, r.pickup_location, r.drop_location,
       r.rental_package, r.waiting_time, r.approx_distance_km, r.distance_km, r.fare,
       r.customer_name, r.mobile, r.email, r.passengers, r.pickup_address,
       coalesce(r.pickup_date, (p.created_at at time zone 'Asia/Kolkata')::date, date '2024-11-01'),
       r.pickup_time, p.advance_amount, r.legacy_id,
       coalesce(p.created_at, (coalesce(r.pickup_date, date '2024-11-01'))::timestamp at time zone 'Asia/Kolkata')
from booking_rows r
left join lateral (select pm.created_at, pm.advance_amount from public.payments pm
                   where pm.booking_id::bigint = r.legacy_id
                   order by pm.created_at desc limit 1) p on true
where r.copy_no = 1
order by r.n;

select setval(pg_get_serial_sequence('public.bookings', 'id'),
              greatest((select max(id) from public.bookings), 999969));

-- duplicate ids get a fresh id
insert into public.bookings (booking_type, car_type, pickup_location, drop_location,
       rental_package, waiting_time, approx_distance_km, distance_km, fare,
       customer_name, mobile, email, passengers, pickup_address, pickup_date, pickup_time, legacy_id)
select booking_type, car_type, pickup_location, drop_location,
       rental_package, waiting_time, approx_distance_km, distance_km, fare,
       customer_name, mobile, email, passengers, pickup_address,
       coalesce(pickup_date, date '2024-11-01'), pickup_time, legacy_id
from booking_rows where copy_no > 1 order by n;

-- link rental packages & routes where the names match
update public.bookings b set rental_package_id = rp.id
from public.rental_packages rp
where b.booking_type = 'local-rental'
  and regexp_replace(lower(b.rental_package), '\s', '', 'g') = rp.hours || 'hour' || rp.km || 'km';

update public.bookings b set route_id = r.id
from public.routes r
join public.locations f on f.id = r.from_location_id
join public.locations t on t.id = r.to_location_id
where b.booking_type = 'oneway' and f.name = b.pickup_location and t.name = b.drop_location;

-- ---------- customers (one per mobile, latest name/email) -------------
insert into public.customers (full_name, mobile, email, created_at)
select distinct on (mobile) customer_name, mobile, email, created_at
from public.bookings
where mobile ~ '^\d{10}$'
order by mobile, id desc;

update public.customers c set created_at = first.created_at
from (select mobile, min(created_at) as created_at from public.bookings group by mobile) first
where first.mobile = c.mobile;

update public.bookings b set customer_id = c.id
from public.customers c where c.mobile = b.mobile;

-- ---------- enquiries ------------------------------------------------
insert into public.enquiries (service_type, pickup, drop_or_package, mobile, created_at, legacy_id)
select case when lower(e->>'dropLocationOrPackages') ~ '\d+\s*hour' then 'local-rental'::public.booking_type end,
       coalesce(pg_temp.place(e->>'pickupLocation'), '-'),
       pg_temp.place(e->>'dropLocationOrPackages'),
       pg_temp.mobile(e->>'mobileNumber'),
       coalesce(pg_temp.enquiry_ts(e->>'date', e->>'time'), now()),
       pg_temp.to_int(e->>'id')
from pg_temp.legacy('enquiry') e;

-- ---------- payments (copied from the live `payments` table) ---------
insert into public.booking_payments (booking_id, customer_name, mobile, booking_amount, advance_amount,
       payment_type, status, payment_link, razorpay_payment_link_id, razorpay_payment_id, reference_id,
       paid_at, webhook_response, legacy_id, created_at, updated_at)
select p.booking_id,
       coalesce(nullif(trim(p.customer_name), ''), '-'),
       coalesce(trim(p.mobile), ''),
       round(coalesce(p.booking_amount, 0))::int,
       round(coalesce(p.advance_amount, 0))::int,
       coalesce(p.payment_type, 'ADVANCE'),
       case when p.status in ('PENDING', 'PAID', 'EXPIRED', 'CANCELLED', 'FAILED') then p.status else 'PENDING' end,
       p.payment_link,
       p.razorpay_payment_link_id,
       nullif(p.razorpay_payment_id, ''),
       p.reference_id,
       p.paid_at at time zone 'UTC',          -- live column is 'timestamp without time zone' (UTC)
       p.webhook_response,
       p.id,
       p.created_at,
       coalesce(p.updated_at, p.created_at)
from public.payments p
where p.booking_id is not null and p.razorpay_payment_link_id is not null
order by p.id
on conflict (razorpay_payment_link_id) do nothing;

alter table public.bookings enable trigger bookings_status_log;

-- remove the temporary helpers
drop function pg_temp.to_int(text), pg_temp.place(text), pg_temp.car(text), pg_temp.btype(text),
              pg_temp.pickup_date(text), pg_temp.mobile(text), pg_temp.enquiry_ts(text, text),
              pg_temp.legacy(text);

commit;

-- ##################### 004_api_support.sql #####################
-- =====================================================================
-- KiteCab v2 — columns used by the Vercel API
-- ip_hash: salted SHA-256 of the client IP (raw IPs are never stored),
--          used only for spam limits.
-- =====================================================================
begin;
alter table public.enquiries add column if not exists ip_hash text;
alter table public.bookings  add column if not exists ip_hash text;

create index if not exists enquiries_ip_recent_idx     on public.enquiries (ip_hash, created_at desc);
create index if not exists enquiries_mobile_recent_idx on public.enquiries (mobile, created_at desc);
create index if not exists bookings_ip_recent_idx      on public.bookings  (ip_hash, created_at desc);

commit;

-- ##################### 005_customer_portal_and_coupons.sql #####################
-- =====================================================================
-- KiteCab v2 — customer login (my bookings + driver details) and coupons
-- New objects only; the live `kitecab` / `payments` tables are untouched.
-- =====================================================================
begin;

-- bookings remember the price before and after a coupon
alter table public.bookings
  add column fare_before_discount int,
  add column discount_amount int not null default 0 check (discount_amount >= 0),
  add column coupon_code text;

-- ---------- customer login ------------------------------------------
-- When someone signs up (phone OTP or email) a `profiles` row is created
-- and, if their phone matches a customer, that customer (with all past
-- bookings) is linked to the login automatically.
create function public.handle_new_auth_user()
returns trigger language plpgsql security definer set search_path = public as $$
declare mobile10 text := right(regexp_replace(coalesce(new.phone, ''), '\D', '', 'g'), 10);
begin
  insert into public.profiles (id, role, mobile)
  values (new.id, 'customer', nullif(mobile10, ''))
  on conflict (id) do nothing;

  if length(mobile10) = 10 then
    update public.customers set auth_user_id = new.id
    where mobile = mobile10 and auth_user_id is null;
  end if;
  return new;
end $$;

create trigger kitecab_on_auth_user_created
  after insert on auth.users
  for each row execute function public.handle_new_auth_user();

-- What a logged-in customer sees: only their own bookings, with the driver
-- and car once one is assigned. Runs with the view owner's rights, so the
-- `where` clause on auth.uid() is the security boundary — keep it.
create view public.my_bookings as
select b.id, b.booking_type, b.car_type, b.status,
       b.pickup_location, b.drop_location, b.rental_package, b.waiting_time,
       b.pickup_address, b.pickup_date, b.pickup_time, b.passengers,
       b.fare, b.fare_before_discount, b.discount_amount, b.coupon_code,
       b.advance_amount,
       (select bp.status from public.booking_payments bp
         where bp.booking_id = b.id order by bp.created_at desc limit 1)       as advance_status,
       (select bp.payment_link from public.booking_payments bp
         where bp.booking_id = b.id and bp.status = 'PENDING'
         order by bp.created_at desc limit 1)                                  as pay_link,
       case when b.status in ('assigned', 'confirmed', 'completed') then d.full_name end       as driver_name,
       case when b.status in ('assigned', 'confirmed') then d.mobile end                       as driver_mobile,
       case when b.status in ('assigned', 'confirmed', 'completed') then v.registration_no end as car_number,
       case when b.status in ('assigned', 'confirmed', 'completed') then v.model end           as car_model,
       b.created_at
from public.bookings b
join public.customers c on c.id = b.customer_id
left join public.drivers d on d.id = b.driver_id
left join public.vehicles v on v.id = b.vehicle_id
where c.auth_user_id = auth.uid();

-- ---------- coupons (ready for later) ----------------------------------
create type public.discount_type as enum ('percent', 'flat');

create table public.coupons (
  id                 bigint generated always as identity primary key,
  code               text not null unique check (code = upper(code) and code ~ '^[A-Z0-9]{3,20}$'),
  description        text,
  discount_type      public.discount_type not null,
  discount_value     int not null check (discount_value > 0),
  max_discount       int check (max_discount > 0),          -- cap for percent coupons
  min_fare           int not null default 0,
  booking_types      public.booking_type[],                  -- null = all trip types
  car_types          public.car_type[],                      -- null = all cars
  pickup_location_ids bigint[],                              -- null = every city
  first_booking_only boolean not null default false,
  usage_limit        int check (usage_limit > 0),            -- null = unlimited
  per_customer_limit int not null default 1 check (per_customer_limit > 0),
  valid_from         timestamptz,
  valid_until        timestamptz,
  is_active          boolean not null default true,
  is_public          boolean not null default false,         -- show on website offers
  created_at         timestamptz not null default now(),
  updated_at         timestamptz not null default now(),
  check (discount_type <> 'percent' or discount_value <= 100),
  check (valid_until is null or valid_from is null or valid_until > valid_from)
);

create table public.coupon_redemptions (
  id              bigint generated always as identity primary key,
  coupon_id       bigint not null references public.coupons(id) on delete restrict,
  booking_id      bigint not null unique references public.bookings(id) on delete cascade,
  customer_id     bigint references public.customers(id) on delete set null,
  mobile          text not null,
  discount_amount int not null check (discount_amount > 0),
  created_at      timestamptz not null default now()
);
create index coupon_redemptions_coupon_idx on public.coupon_redemptions (coupon_id);
create index coupon_redemptions_mobile_idx on public.coupon_redemptions (mobile);

create trigger coupons_touch before update on public.coupons
  for each row execute function public.touch_updated_at();

-- ---------- security --------------------------------------------------
alter table public.coupons            enable row level security;
alter table public.coupon_redemptions enable row level security;

create policy "admin all coupons" on public.coupons
  for all using (public.is_admin()) with check (public.is_admin());
create policy "public read live public coupons" on public.coupons
  for select using (is_active and is_public
                    and (valid_from is null or valid_from <= now())
                    and (valid_until is null or valid_until > now()));
create policy "admin all coupon_redemptions" on public.coupon_redemptions
  for all using (public.is_admin()) with check (public.is_admin());

revoke all on public.coupons, public.coupon_redemptions, public.my_bookings from anon, authenticated;
grant select on public.coupons to anon, authenticated;
grant insert, update, delete on public.coupons to authenticated;
grant select, insert, update, delete on public.coupon_redemptions to authenticated;
grant select on public.my_bookings to authenticated;

commit;

-- ##################### 006_admin_fast_lists.sql #####################
-- =====================================================================
-- KiteCab v2 — admin panel speed: search indexes, list views, dashboard RPC
-- New objects only; live `kitecab` / `payments` untouched. NOT YET TESTED.
-- =====================================================================
begin;

create extension if not exists pg_trgm;

-- fast "contains" search on names / places, prefix search on mobiles
create index if not exists bookings_name_trgm      on public.bookings  using gin (customer_name gin_trgm_ops);
create index if not exists bookings_mobile_prefix  on public.bookings  (mobile text_pattern_ops);
create index if not exists bookings_status_date    on public.bookings  (status, pickup_date desc);
create index if not exists customers_name_trgm     on public.customers using gin (full_name gin_trgm_ops);
create index if not exists customers_mobile_prefix on public.customers (mobile text_pattern_ops);
create index if not exists enquiries_pickup_trgm   on public.enquiries using gin (pickup gin_trgm_ops);
create index if not exists booking_payments_status on public.booking_payments (status, created_at desc);

-- Booking list row with latest advance status. security_invoker = RLS applies (admin only).
-- Scalar subqueries run only for the 25 rows of the page.
create view public.admin_bookings with (security_invoker = true) as
select b.id, b.booking_type, b.car_type, b.status, b.pickup_location, b.drop_location, b.rental_package,
       b.pickup_date, b.pickup_time, b.fare, b.advance_amount, b.customer_name, b.mobile,
       b.driver_id, b.created_at,
       (select d.full_name from public.drivers d where d.id = b.driver_id) as driver_name,
       (select bp.status from public.booking_payments bp
         where bp.booking_id = b.id order by bp.created_at desc limit 1)  as advance_status
from public.bookings b;

create view public.admin_customers with (security_invoker = true) as
select c.id, c.full_name, c.mobile, c.email, c.created_at,
       (select count(*) from public.bookings b where b.customer_id = c.id)            as bookings,
       (select coalesce(sum(b.fare), 0) from public.bookings b
         where b.customer_id = c.id and b.status <> 'cancelled')                       as total_fare,
       (select max(b.pickup_date) from public.bookings b where b.customer_id = c.id)  as last_trip
from public.customers c;

create view public.admin_routes with (security_invoker = true) as
select r.id, r.from_location_id, r.to_location_id, f.name as pickup, t.name as drop,
       r.distance_km, r.hatchback_price, r.sedan_price, r.suv_price, r.is_active
from public.routes r
join public.locations f on f.id = r.from_location_id
join public.locations t on t.id = r.to_location_id;

-- Dashboard numbers in ONE call.
create function public.admin_dashboard()
returns jsonb language plpgsql stable security invoker set search_path = public as $$
declare today date := (now() at time zone 'Asia/Kolkata')::date;
begin
  if not public.is_admin() then raise exception 'admin only'; end if;
  return jsonb_build_object(
    'bookings_today',   (select count(*) from bookings where (created_at at time zone 'Asia/Kolkata')::date = today),
    'bookings_yesterday', (select count(*) from bookings where (created_at at time zone 'Asia/Kolkata')::date = today - 1),
    'pickups_today',    (select count(*) from bookings where pickup_date = today and status <> 'cancelled'),
    'pickups_no_driver',(select count(*) from bookings where pickup_date = today and status <> 'cancelled' and driver_id is null),
    'advance_week',     (select coalesce(sum(amount_paid), 0) from booking_payments
                          where status = 'PAID' and paid_at >= now() - interval '7 days'),
    'enquiries_today',  (select count(*) from enquiries where (created_at at time zone 'Asia/Kolkata')::date = today)
  );
end $$;

revoke all on public.admin_bookings, public.admin_customers, public.admin_routes from anon;
grant select on public.admin_bookings, public.admin_customers, public.admin_routes to authenticated;
revoke execute on function public.admin_dashboard() from anon, public;
grant execute on function public.admin_dashboard() to authenticated;

commit;

-- ##################### 007_admin_stats.sql #####################
-- =====================================================================
-- KiteCab v2 — richer admin dashboard numbers in ONE call.
-- New function only; nothing existing changes. Admin only (is_admin()).
-- =====================================================================
begin;

create function public.admin_stats(p_days int default 30)
returns jsonb language plpgsql stable security invoker set search_path = public as $$
declare
  today   date := (now() at time zone 'Asia/Kolkata')::date;
  since   date := today - (least(greatest(p_days, 7), 365) - 1);
  m_start date := date_trunc('month', today)::date;
  pm_start date := (date_trunc('month', today) - interval '1 month')::date;
begin
  if not public.is_admin() then raise exception 'admin only'; end if;

  return jsonb_build_object(
    -- bookings and enquiries per day (India time), zero-filled
    'daily', (
      select jsonb_agg(jsonb_build_object('day', d::date, 'bookings', coalesce(b.n, 0), 'enquiries', coalesce(e.n, 0)) order by d)
      from generate_series(since, today, interval '1 day') d
      left join (select (created_at at time zone 'Asia/Kolkata')::date as day, count(*) n
                   from bookings where created_at >= since::timestamp at time zone 'Asia/Kolkata' group by 1) b on b.day = d::date
      left join (select (created_at at time zone 'Asia/Kolkata')::date as day, count(*) n
                   from enquiries where created_at >= since::timestamp at time zone 'Asia/Kolkata' group by 1) e on e.day = d::date
    ),
    -- this month vs last month (same number of days, so the comparison is fair)
    'month', (
      select jsonb_build_object(
        'bookings',      count(*) filter (where c >= m_start),
        'fare',          coalesce(sum(fare) filter (where c >= m_start and status <> 'cancelled'), 0),
        'prev_bookings', count(*) filter (where c >= pm_start and c < pm_start + (today - m_start + 1)),
        'prev_fare',     coalesce(sum(fare) filter (where c >= pm_start and c < pm_start + (today - m_start + 1) and status <> 'cancelled'), 0)
      )
      from (select (created_at at time zone 'Asia/Kolkata')::date c, fare, status from bookings
             where created_at >= pm_start::timestamp at time zone 'Asia/Kolkata') x
    ),
    'by_type', (
      select coalesce(jsonb_object_agg(booking_type, n), '{}') from (
        select booking_type, count(*) n from bookings
        where created_at >= since::timestamp at time zone 'Asia/Kolkata' group by 1) t
    ),
    'by_status', (
      select coalesce(jsonb_object_agg(status, n), '{}') from (
        select status, count(*) n from bookings
        where created_at >= since::timestamp at time zone 'Asia/Kolkata' group by 1) t
    ),
    'top_routes', (
      select coalesce(jsonb_agg(r), '[]') from (
        select pickup_location as pickup, coalesce(drop_location, rental_package, '-') as drop, count(*) as bookings,
               coalesce(sum(fare) filter (where status <> 'cancelled'), 0) as fare
        from bookings where created_at >= since::timestamp at time zone 'Asia/Kolkata'
        group by 1, 2 order by 3 desc, 4 desc limit 8) r
    ),
    'advance', (
      select jsonb_build_object(
        'paid',    coalesce(sum(coalesce(amount_paid, advance_amount)) filter (where status = 'PAID'), 0),
        'paid_n',  count(*) filter (where status = 'PAID'),
        'pending_n', count(*) filter (where status = 'PENDING'))
      from booking_payments where created_at >= since::timestamp at time zone 'Asia/Kolkata'
    ),
    -- future trips that still need a driver (next 7 days)
    'needs_driver', (
      select count(*) from bookings
      where pickup_date between today and today + 7 and driver_id is null and status not in ('cancelled', 'completed')
    )
  );
end $$;

revoke execute on function public.admin_stats(int) from anon, public;
grant execute on function public.admin_stats(int) to authenticated;

commit;

-- ##################### 008_crm_staff_followups.sql #####################
-- =====================================================================
-- KiteCab v2 — office workflow: staff logins, enquiry follow-ups,
-- richer bookings and an automatic activity log (who did what, when).
-- New objects / new columns only. Live `kitecab` / `payments` untouched.
-- =====================================================================

-- Enum values must be committed before use, so this runs outside the transaction.
alter type public.user_role add value if not exists 'staff';

begin;

-- ---------- who is office staff --------------------------------------
-- Staff = admin or staff. Text compare, so it works in the same script as the new enum value.
create function public.is_staff()
returns boolean language sql stable security definer set search_path = public as $$
  select exists (select 1 from public.profiles p where p.id = auth.uid() and p.role::text in ('admin', 'staff'))
$$;

create function public.staff_name(uid uuid)
returns text language sql stable security definer set search_path = public as $$
  select coalesce(nullif(p.full_name, ''), u.email, 'System')
  from auth.users u left join public.profiles p on p.id = u.id where u.id = uid
$$;

-- ---------- enquiries become leads ------------------------------------
create type public.lead_status as enum ('new', 'contacted', 'follow_up', 'converted', 'not_interested', 'invalid');

alter table public.enquiries
  add column status            public.lead_status not null default 'new',
  add column customer_name     text,
  add column quoted_fare       int,
  add column assigned_to       uuid references auth.users(id) on delete set null,
  add column next_follow_up_at timestamptz,
  add column last_contacted_at timestamptz,
  add column attempts          int not null default 0,
  add column note              text,
  add column lost_reason       text,
  add column booking_id        bigint references public.bookings(id) on delete set null,
  add column source            text not null default 'website',
  add column updated_at        timestamptz not null default now();

create index enquiries_status_idx   on public.enquiries (status, created_at desc);
create index enquiries_followup_idx on public.enquiries (next_follow_up_at) where status in ('new', 'contacted', 'follow_up');
create index enquiries_mobile_idx   on public.enquiries (mobile text_pattern_ops);

create trigger enquiries_touch before update on public.enquiries
  for each row execute function public.touch_updated_at();

-- One row per call / WhatsApp / note on a lead.
create table public.enquiry_followups (
  id           bigint generated always as identity primary key,
  enquiry_id   bigint not null references public.enquiries(id) on delete cascade,
  staff_id     uuid default auth.uid() references auth.users(id) on delete set null,
  channel      text not null default 'call' check (channel in ('call', 'whatsapp', 'note')),
  outcome      text not null check (outcome in ('no_answer', 'busy', 'interested', 'call_back', 'booked', 'not_interested', 'wrong_number', 'note')),
  note         text,
  next_at      timestamptz,
  created_at   timestamptz not null default now()
);
create index enquiry_followups_enquiry_idx on public.enquiry_followups (enquiry_id, created_at desc);
create index enquiry_followups_staff_idx   on public.enquiry_followups (staff_id, created_at desc);

-- A follow-up updates its lead: status, attempts, next date, last contacted.
create function public.apply_followup()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  update public.enquiries e set
    attempts          = e.attempts + case when new.channel = 'note' then 0 else 1 end,
    last_contacted_at = case when new.channel = 'note' then e.last_contacted_at else new.created_at end,
    next_follow_up_at = case when new.outcome in ('booked', 'not_interested', 'wrong_number') then null
                             else coalesce(new.next_at, e.next_follow_up_at) end,
    assigned_to       = coalesce(e.assigned_to, new.staff_id),
    status = (case new.outcome
               when 'booked'         then 'converted'
               when 'not_interested' then 'not_interested'
               when 'wrong_number'   then 'invalid'
               when 'note'           then e.status::text
               else case when new.next_at is not null or new.outcome in ('interested', 'call_back')
                         then 'follow_up' else 'contacted' end
             end)::public.lead_status,
    lost_reason = case when new.outcome in ('not_interested', 'wrong_number') then coalesce(new.note, e.lost_reason) else e.lost_reason end
  where e.id = new.enquiry_id and (e.status <> 'converted' or new.outcome = 'note');
  return new;
end $$;

create trigger enquiry_followups_apply after insert on public.enquiry_followups
  for each row execute function public.apply_followup();

-- ---------- bookings: office fields -----------------------------------
alter table public.bookings
  add column source            text not null default 'website' check (source in ('website', 'phone', 'whatsapp', 'walk_in', 'repeat', 'other')),
  add column created_by        uuid references auth.users(id) on delete set null,
  add column handled_by        uuid references auth.users(id) on delete set null,
  add column enquiry_id        bigint references public.enquiries(id) on delete set null,
  add column cancel_reason     text,
  add column cancelled_at      timestamptz,
  add column completed_at      timestamptz,
  add column balance_collected int check (balance_collected >= 0),
  add column balance_mode      text check (balance_mode in ('cash', 'upi', 'card', 'bank')),
  add column extra_charges     int not null default 0 check (extra_charges >= 0),
  add column extra_note        text,
  add column customer_rating   int check (customer_rating between 1 and 5),
  add column feedback          text;

create index bookings_source_idx  on public.bookings (source, created_at desc);
create index bookings_handled_idx on public.bookings (handled_by);

-- A new booking from the same mobile closes that person's open leads (last 7 days).
create function public.link_booking_to_lead()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  update public.enquiries set status = 'converted', booking_id = new.id, next_follow_up_at = null
  where mobile = new.mobile and status in ('new', 'contacted', 'follow_up')
    and created_at > now() - interval '7 days';
  return new;
end $$;

create trigger bookings_link_lead after insert on public.bookings
  for each row execute function public.link_booking_to_lead();

-- ---------- activity log (automatic) ----------------------------------
create table public.activity_log (
  id          bigint generated always as identity primary key,
  actor_id    uuid default auth.uid(),
  entity      text not null,            -- booking, enquiry, route, setting ...
  entity_id   text not null,
  action      text not null,            -- created, status, driver, fare, follow_up ...
  detail      text,
  created_at  timestamptz not null default now()
);
create index activity_log_entity_idx on public.activity_log (entity, entity_id, created_at desc);
create index activity_log_actor_idx  on public.activity_log (actor_id, created_at desc);
create index activity_log_time_idx   on public.activity_log (created_at desc);

create function public.log_booking_activity()
returns trigger language plpgsql security definer set search_path = public as $$
declare who uuid := auth.uid();
begin
  if tg_op = 'INSERT' then
    insert into activity_log (actor_id, entity, entity_id, action, detail)
    values (who, 'booking', new.id, 'created', new.source || ' · ' || new.pickup_location || ' → ' || coalesce(new.drop_location, new.rental_package, '') || ' · ₹' || new.fare);
    return new;
  end if;
  if new.status is distinct from old.status then
    insert into activity_log (actor_id, entity, entity_id, action, detail)
    values (who, 'booking', new.id, 'status', old.status || ' → ' || new.status || coalesce(' · ' || new.cancel_reason, ''));
  end if;
  if new.driver_id is distinct from old.driver_id or new.vehicle_id is distinct from old.vehicle_id then
    insert into activity_log (actor_id, entity, entity_id, action, detail)
    values (who, 'booking', new.id, 'driver',
            coalesce((select full_name from drivers where id = new.driver_id), 'removed') ||
            coalesce(' · ' || (select registration_no from vehicles where id = new.vehicle_id), ''));
  end if;
  if new.fare is distinct from old.fare then
    insert into activity_log (actor_id, entity, entity_id, action, detail)
    values (who, 'booking', new.id, 'fare', '₹' || old.fare || ' → ₹' || new.fare);
  end if;
  if new.pickup_date is distinct from old.pickup_date or new.pickup_time is distinct from old.pickup_time then
    insert into activity_log (actor_id, entity, entity_id, action, detail)
    values (who, 'booking', new.id, 'pickup', new.pickup_date || ' ' || new.pickup_time);
  end if;
  if new.balance_collected is distinct from old.balance_collected and new.balance_collected is not null then
    insert into activity_log (actor_id, entity, entity_id, action, detail)
    values (who, 'booking', new.id, 'collected', '₹' || new.balance_collected || coalesce(' by ' || new.balance_mode, ''));
  end if;
  return new;
end $$;

create trigger bookings_activity after insert or update on public.bookings
  for each row execute function public.log_booking_activity();

create function public.log_followup_activity()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  insert into activity_log (actor_id, entity, entity_id, action, detail)
  values (new.staff_id, 'enquiry', new.enquiry_id, 'follow_up', new.channel || ' · ' || new.outcome || coalesce(' · ' || new.note, ''));
  return new;
end $$;

create trigger enquiry_followups_activity after insert on public.enquiry_followups
  for each row execute function public.log_followup_activity();

-- ---------- list views for the office --------------------------------
create view public.admin_enquiries with (security_invoker = true) as
select e.*,
       public.staff_name(e.assigned_to) as assigned_name,
       (select count(*) from public.bookings b where b.mobile = e.mobile) as past_bookings
from public.enquiries e;

create view public.admin_activity with (security_invoker = true) as
select a.*, public.staff_name(a.actor_id) as actor_name from public.activity_log a;

-- Staff list (names + role). Runs with owner rights to read auth.users, so the
-- is_staff() filter below is what keeps it private — keep it.
create view public.admin_staff as
select p.id, p.role::text as role, p.full_name, p.mobile, u.email, u.last_sign_in_at, p.created_at
from public.profiles p join auth.users u on u.id = p.id
where p.role::text in ('admin', 'staff') and public.is_staff();

-- admin_bookings gets the new office columns (same name, new definition is ours).
create or replace view public.admin_bookings with (security_invoker = true) as
select b.id, b.booking_type, b.car_type, b.status, b.pickup_location, b.drop_location, b.rental_package,
       b.pickup_date, b.pickup_time, b.fare, b.advance_amount, b.customer_name, b.mobile,
       b.driver_id, b.created_at,
       (select d.full_name from public.drivers d where d.id = b.driver_id) as driver_name,
       (select bp.status from public.booking_payments bp
         where bp.booking_id = b.id order by bp.created_at desc limit 1)  as advance_status,
       b.source, b.handled_by, public.staff_name(b.handled_by) as handled_name, b.balance_collected
from public.bookings b;

-- ---------- staff management + performance ----------------------------
create function public.admin_set_staff(p_email text, p_role text, p_name text default null)
returns text language plpgsql security definer set search_path = public as $$
declare uid uuid;
begin
  if not public.is_admin() then raise exception 'admin only'; end if;
  if p_role not in ('admin', 'staff', 'customer') then raise exception 'role must be admin, staff or customer'; end if;
  select id into uid from auth.users where lower(email) = lower(trim(p_email));
  if uid is null then raise exception 'No login with this email. Create it first in Supabase → Authentication → Users.'; end if;
  if uid = auth.uid() and p_role <> 'admin' then raise exception 'You cannot remove your own admin access.'; end if;
  insert into public.profiles (id, role, full_name) values (uid, p_role::public.user_role, nullif(trim(p_name), ''))
  on conflict (id) do update set role = excluded.role, full_name = coalesce(excluded.full_name, profiles.full_name);
  insert into public.activity_log (entity, entity_id, action, detail) values ('staff', uid, 'role', p_email || ' → ' || p_role);
  return uid::text;
end $$;

create function public.staff_performance(p_days int default 7)
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare since timestamptz := now() - make_interval(days => least(greatest(p_days, 1), 365));
begin
  if not public.is_admin() then raise exception 'admin only'; end if;
  return coalesce((
    select jsonb_agg(row_to_json(t) order by t.follow_ups desc) from (
      select s.id, coalesce(nullif(s.full_name, ''), s.email) as name, s.role,
             (select count(*) from enquiry_followups f where f.staff_id = s.id and f.created_at >= since and f.channel <> 'note') as follow_ups,
             (select count(*) from enquiry_followups f where f.staff_id = s.id and f.created_at >= since and f.outcome = 'booked') as converted,
             (select count(*) from enquiry_followups f where f.staff_id = s.id and f.created_at >= since and f.outcome in ('no_answer', 'busy')) as not_reached,
             (select count(*) from bookings b where b.created_by = s.id and b.created_at >= since) as bookings_created,
             (select count(*) from activity_log a where a.actor_id = s.id and a.entity = 'booking' and a.action = 'driver' and a.created_at >= since) as drivers_assigned,
             (select count(*) from enquiries e where e.assigned_to = s.id and e.status in ('new', 'contacted', 'follow_up')) as open_leads,
             (select count(*) from enquiries e where e.assigned_to = s.id and e.status in ('new', 'contacted', 'follow_up') and e.next_follow_up_at < now()) as overdue,
             (select max(a.created_at) from activity_log a where a.actor_id = s.id) as last_active
      from public.admin_staff s) t
  ), '[]'::jsonb);
end $$;

-- Lead counts per tab in one call.
create function public.lead_counts()
returns jsonb language sql stable security invoker set search_path = public as $$
  select jsonb_build_object(
    'new',            count(*) filter (where status = 'new'),
    'due',            count(*) filter (where status in ('new', 'contacted', 'follow_up') and next_follow_up_at <= now()),
    'follow_up',      count(*) filter (where status = 'follow_up'),
    'contacted',      count(*) filter (where status = 'contacted'),
    'converted',      count(*) filter (where status = 'converted'),
    'not_interested', count(*) filter (where status = 'not_interested'),
    'invalid',        count(*) filter (where status = 'invalid'),
    'today',          count(*) filter (where created_at >= (date_trunc('day', now() at time zone 'Asia/Kolkata') at time zone 'Asia/Kolkata'))
  ) from public.enquiries
$$;

-- Dashboard + stats: staff may see them too.
create or replace function public.admin_dashboard()
returns jsonb language plpgsql stable security invoker set search_path = public as $$
declare today date := (now() at time zone 'Asia/Kolkata')::date;
begin
  if not public.is_staff() then raise exception 'staff only'; end if;
  return jsonb_build_object(
    'bookings_today',   (select count(*) from bookings where (created_at at time zone 'Asia/Kolkata')::date = today),
    'bookings_yesterday', (select count(*) from bookings where (created_at at time zone 'Asia/Kolkata')::date = today - 1),
    'pickups_today',    (select count(*) from bookings where pickup_date = today and status <> 'cancelled'),
    'pickups_no_driver',(select count(*) from bookings where pickup_date = today and status not in ('cancelled', 'completed') and driver_id is null),
    'advance_week',     (select coalesce(sum(amount_paid), 0) from booking_payments
                          where status = 'PAID' and paid_at >= now() - interval '7 days'),
    'enquiries_today',  (select count(*) from enquiries where (created_at at time zone 'Asia/Kolkata')::date = today),
    'leads_due',        (select count(*) from enquiries where status in ('new', 'contacted', 'follow_up') and coalesce(next_follow_up_at, created_at) <= now()),
    'leads_new',        (select count(*) from enquiries where status = 'new')
  );
end $$;

-- ---------- security ---------------------------------------------------
alter table public.enquiry_followups enable row level security;
alter table public.activity_log      enable row level security;

-- Staff work on leads, bookings, customers; read drivers, cars, payments, catalogue.
do $$
declare t text;
begin
  foreach t in array array['enquiries', 'enquiry_followups', 'bookings', 'customers']
  loop
    execute format('create policy "staff all %1$s" on public.%1$I for all using (public.is_staff()) with check (public.is_staff())', t);
  end loop;
  foreach t in array array['drivers', 'vehicles', 'booking_payments', 'booking_status_history', 'activity_log', 'profiles', 'settings']
  loop
    execute format('create policy "staff read %1$s" on public.%1$I for select using (public.is_staff())', t);
  end loop;
end $$;
create policy "staff write activity" on public.activity_log for insert with check (public.is_staff() and actor_id = auth.uid());

revoke all on public.enquiry_followups, public.activity_log, public.admin_enquiries, public.admin_activity, public.admin_staff from anon;
grant select, insert on public.enquiry_followups to authenticated;
grant select, insert on public.activity_log to authenticated;
grant select on public.admin_enquiries, public.admin_activity, public.admin_staff to authenticated;
revoke execute on function public.admin_set_staff(text, text, text), public.staff_performance(int), public.lead_counts() from anon, public;
grant execute on function public.admin_set_staff(text, text, text), public.staff_performance(int), public.lead_counts() to authenticated;

commit;

-- ##################### 009_lead_due_fix.sql #####################
-- =====================================================================
-- KiteCab v2 — "Call now" counts new leads that have no follow-up time yet
-- (same rule as the Enquiries list). Admin login gets a display name.
-- =====================================================================
begin;

create or replace function public.lead_counts()
returns jsonb language sql stable security invoker set search_path = public as $$
  select jsonb_build_object(
    'new',            count(*) filter (where status = 'new'),
    'due',            count(*) filter (where status in ('new', 'contacted', 'follow_up') and (next_follow_up_at is null or next_follow_up_at <= now())),
    'follow_up',      count(*) filter (where status = 'follow_up'),
    'contacted',      count(*) filter (where status = 'contacted'),
    'converted',      count(*) filter (where status = 'converted'),
    'not_interested', count(*) filter (where status = 'not_interested'),
    'invalid',        count(*) filter (where status = 'invalid'),
    'today',          count(*) filter (where created_at >= (date_trunc('day', now() at time zone 'Asia/Kolkata') at time zone 'Asia/Kolkata'))
  ) from public.enquiries
$$;

update public.profiles p set full_name = 'KiteCab Admin'
from auth.users u
where u.id = p.id and u.email = 'kitecabtaxiservice@gmail.com' and coalesce(p.full_name, '') = '';

commit;

-- ##################### 010_staff_converted.sql #####################
-- =====================================================================
-- KiteCab v2 — "Leads booked" counts bookings a person made from a lead,
-- plus leads they marked Booked (the same lead is never counted twice).
-- =====================================================================
begin;

create or replace function public.staff_performance(p_days int default 7)
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare since timestamptz := now() - make_interval(days => least(greatest(p_days, 1), 365));
begin
  if not public.is_admin() then raise exception 'admin only'; end if;
  return coalesce((
    select jsonb_agg(row_to_json(t) order by t.follow_ups desc) from (
      select s.id, coalesce(nullif(s.full_name, ''), s.email) as name, s.role,
             (select count(*) from enquiry_followups f where f.staff_id = s.id and f.created_at >= since and f.channel <> 'note') as follow_ups,
             (select count(*) from bookings b where b.created_by = s.id and b.enquiry_id is not null and b.created_at >= since)
             + (select count(*) from enquiry_followups f where f.staff_id = s.id and f.created_at >= since and f.outcome = 'booked'
                  and not exists (select 1 from bookings b2 where b2.enquiry_id = f.enquiry_id and b2.created_by = s.id)) as converted,
             (select count(*) from enquiry_followups f where f.staff_id = s.id and f.created_at >= since and f.outcome in ('no_answer', 'busy')) as not_reached,
             (select count(*) from bookings b where b.created_by = s.id and b.created_at >= since) as bookings_created,
             (select count(*) from activity_log a where a.actor_id = s.id and a.entity = 'booking' and a.action = 'driver' and a.created_at >= since) as drivers_assigned,
             (select count(*) from enquiries e where e.assigned_to = s.id and e.status in ('new', 'contacted', 'follow_up')) as open_leads,
             (select count(*) from enquiries e where e.assigned_to = s.id and e.status in ('new', 'contacted', 'follow_up') and e.next_follow_up_at < now()) as overdue,
             (select max(a.created_at) from activity_log a where a.actor_id = s.id) as last_active
      from public.admin_staff s) t
  ), '[]'::jsonb);
end $$;

commit;

-- ##################### 011_fast_create_booking.sql #####################
-- =====================================================================
-- KiteCab v2 — save customer + booking in ONE database call (faster booking).
-- Called only by the backend (secret key); not callable from the browser.
-- =====================================================================
begin;

create function public.create_booking(p_customer jsonb, p_booking jsonb)
returns jsonb language plpgsql security definer set search_path = public as $$
declare
  cid bigint;
  r   public.bookings;
  saved public.bookings;
begin
  insert into public.customers (full_name, mobile, email)
  values (p_customer->>'full_name', p_customer->>'mobile', nullif(p_customer->>'email', ''))
  on conflict (mobile) do update
    set full_name = excluded.full_name,
        email     = coalesce(excluded.email, public.customers.email)
  returning id into cid;

  r := jsonb_populate_record(null::public.bookings, p_booking);
  insert into public.bookings (
    booking_type, car_type, pickup_location, drop_location, route_id, rental_package_id, rental_package,
    waiting_time, approx_distance_km, distance_km, fare, advance_percent, advance_amount,
    customer_id, customer_name, mobile, email, passengers, pickup_address, pickup_date, pickup_time, ip_hash
  ) values (
    r.booking_type, r.car_type, r.pickup_location, r.drop_location, r.route_id, r.rental_package_id, r.rental_package,
    r.waiting_time, r.approx_distance_km, r.distance_km, r.fare, r.advance_percent, r.advance_amount,
    cid, r.customer_name, r.mobile, r.email, r.passengers, r.pickup_address, r.pickup_date, r.pickup_time, r.ip_hash
  )
  returning * into saved;

  return to_jsonb(saved);
end $$;

revoke execute on function public.create_booking(jsonb, jsonb) from public, anon, authenticated;

commit;

